import { MATERIALS,SOURCES,MANAGEMENT_CARDS } from './materials.js';
const $=id=>document.getElementById(id),uid=()=>crypto.randomUUID();
export function createLearningUI(api){
 const {journal,state,observer,panel,close,toast,escape:e,download}=api;
 const name=id=>CATALOG[id]?.name.split(' – ')[0]||id;
 const context=()=>({...api.context(),initialSeed:state.initialSeed,worldVersion:state.worldVersion,simulationTime:state.time,window:state.ecology.window});
 const status=message=>{if($('learning-status'))$('learning-status').textContent=message;toast(message);};
 const safe=fn=>{try{return fn();}catch(error){status(error.message);if(journal.error||journal.readBlocked)api.setDirty(true);return false;}};
 const option=(value,label,chosen)=>`<option value="${e(value)}"${chosen===value?' selected':''}>${e(label)}</option>`;
 const select=(id,label,rows,value)=>`<label>${e(label)}<select id="${id}"><option value="">Bitte wählen …</option>${rows.map(([v,l])=>option(v,l,value)).join('')}</select></label>`;
 const checks=(id,rows,values=[])=>`<fieldset><legend>${e(id==='features'?'Meine erkannten Merkmale':id==='criteria'?'Meine Entscheidungskriterien':'Belege auswählen')}</legend>${rows.map(([v,l])=>`<label class="check"><input type="checkbox" name="${id}" value="${e(v)}"${values.includes(v)?' checked':''}>${e(l)}</label>`).join('')}</fieldset>`;
 const selected=id=>Array.from(document.querySelectorAll(`input[name="${id}"]:checked`),x=>x.value);
 const answer=id=>({...journal.data.learning.answers[id],...journal.data.learning.drafts[id]});
 function refreshHud(){const id=journal.data.learning.activeMission;$('objective').textContent=id?`${id} · ${MISSIONS.find(m=>m.id===id).title}`:'Freie Erkundung';$('objective').dataset.activeMission=id||'free';}
 function persist(changes){journal.updateLearning(changes);api.setDirty(false);api.refresh();refreshHud();}
 function autosave(id,read){for(const el of $('task-form').querySelectorAll('input,textarea,select'))el.addEventListener('input',()=>safe(()=>{persist({drafts:{...journal.data.learning.drafts,[id]:read()}});}));}
 function submit(id,read){$('save-task').onclick=()=>safe(()=>{const value=read();journal.answer(id,value);persist({drafts:{...journal.data.learning.drafts,[id]:value}});const r=assessMission(id,journal.data);$('task-feedback').textContent=(r.complete?'Strukturierte Belegprüfung erfüllt. ':'Noch offen: ')+r.message+' Die freie Begründung bleibt Grundlage der Besprechung und muss als eigenes Arbeitsprodukt vorliegen.';});}
 function hub(){const l=journal.data.learning;panel(`<span class="eyebrow">FRAGEN VERFOLGEN</span><h2>Wähle deinen Erkenntnisweg.</h2><p>Ein Ziel gleichzeitig. Du musst weder alle Familien noch alle Organismen sammeln. Beobachtung, Modellprotokoll und bereitgestelltes Wissen haben verschiedene Herkunft.</p><label>Anforderungsniveau<select id="level">${option('gA','gA · Kernuntersuchung',l.level)}${option('eA','eA · zusätzlich Flächenprobe und Datenmodelle',l.level)}</select></label><div class="actions"><button id="free-play">Frei erkunden</button><button id="materials">Lern- und Quellenkarten</button><button id="analysis">Datenmodelle</button></div>${MISSIONS.map(m=>{const r=assessMission(m.id,journal.data);return `<article><span class="badge">${m.id} · ${r.complete?'Belege strukturiert vollständig':'Untersuchung offen'}</span><h3>${e(m.title)}</h3><p>${e(m.goal)}</p><button data-mission="${m.id}">Untersuchung öffnen</button><details><summary>Zeit und Herkunft</summary><p>${e(m.minutes)}. Die automatische Prüfung bewertet Belegstruktur, nicht die Qualität freier Erklärungen.</p></details></article>`;}).join('')}<p id="learning-status" role="alert"></p>`);
  $('level').onchange=()=>safe(()=>persist({level:$('level').value}));$('free-play').onclick=()=>safe(()=>{persist({activeMission:null});close();});$('materials').onclick=materials;$('analysis').onclick=analysis;$('panel-body').querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>safe(()=>{persist({activeMission:b.dataset.mission});task(b.dataset.mission);}));
 }
 function task(id){const m=MISSIONS.find(m=>m.id===id),a=answer(id),l=journal.data.learning;let body='';
  if(id==='K1'){
   const candidates=journal.data.records.filter(r=>KEY_OPTIONS[r.taxon]),current=candidates.find(r=>r.id===a.recordId)||candidates[0],k=KEY_OPTIONS[current?.taxon];
   body=`<p>Untersuche Waldkern und hellen Saum mit der Lupe oder derselben vergrößerten Modellansicht. Sichere drei verschiedene Funde. Am Ort kannst du methodengleiche Standortprotokolle aufnehmen.</p>${select('determination-record','Fundbeleg',candidates.map(r=>[r.id,`${fundLabel(r,journal.data)} · ${r.siteId||'Ort nicht vermerkt'}`]),current?.id)}<div id="key-fields">${k?checks('features',OBSERVABLE_FEATURES.map(f=>[f,FEATURE_LABELS[f]||f]),a.features||[])+select('choice','Meine Bestimmung',DETERMINATION_CHOICES,a.choice)+select('limit','Begründete Grenze',k.limits.map(x=>[x,FEATURE_LABELS[x]]),a.limit):'<p>Noch kein passender Fundbeleg. Bestimme keinen Programmnamen auswendig.</p>'}</div><button id="add-determination"${k?'':' disabled'}>Diesen Bestimmungsweg hinzufügen</button><ul>${(a.determinations||[]).map(d=>`<li>${e(fundLabel(journal.data.records.find(r=>r.id===d.recordId),journal.data))} · ${e(DETERMINATION_CHOICES.find(([id])=>id===d.choice)?.[1]||'noch keine Auswahl')} · ${e(d.limit||'zwei Merkmale')} · ${validDetermination(journal.data.records.find(r=>r.id===d.recordId),d)?'Merkmalsweg formal stimmig':'Merkmalsweg prüfen'}</li>`).join('')}</ul><p>Standortprotokolle: ${l.measurements.length}. Zeigerwerte mit Fundstellen stehen auf C04; x ist indifferent, kein Nullwert. Transfer: Untersuche einen noch unbenannten Zweig am hellen Waldort und vergleiche Stiel- und Traubeneiche. Fehlen Früchte oder Feinmerkmale, bleibt eine begründete Eichen-Gruppe zulässig.</p>`;
  }else if(id==='K2'){
   const events=journal.data.records.flatMap(r=>(r.events||[]).map(ev=>[eventReference(r,ev),`${ev.interaction}: ${ev.outcome} · ${ev.resourceId} · Rundgang ${r.runId} · Modellzeit ${r.simulationTime.toFixed(1)} s · Beleg ${r.id}`])),chosenEvents=selectedEventRows(journal.data.records,a.eventIds||[]).map(({record,event})=>eventReference(record,event));
   body=`<p>Wähle einen lokalen Fall. Für Konkurrenz kannst du den kontrollierten Versuch ohne/mit Mitnutzer ausführen. Für einen Vorgangsfall benötigst du einen selbst gesicherten Ereignisbeleg.</p>${select('case-id','Fall',INTERACTIONS.filter(i=>!['root-fungus','fungus-wood','shore-feeding','shore-niche','communication'].includes(i.id)).map(i=>[i.id,i.id+' · '+i.kind]),a.caseId||'shell-competition')}<details><summary>Kontrollierter Konkurrenzversuch</summary><p>Nur der Mitnutzer wird verändert. Startpool 12, gleicher Seed, 12 Begegnungsschritte. Dies ist ein ausdrücklich gestaltetes Zusatzmodell, keine Naturmessung.</p>${select('experiment-tide','Tidebedingungen',[['exposed','Trockenfallend / zugänglich'],['covered','Bedeckt / für diesen Muschelversuch nicht zugänglich']],a.experimentTide||'exposed')}<div class="actions"><button type="button" id="run-control">Ohne Mitnutzer ausführen</button><button type="button" id="run-competitor">Mit Mitnutzer ausführen</button></div><div id="experiment-table">${experimentTable(l.experiments)}</div></details>${select('control-id','Kontrolllauf',l.experiments.map(x=>[x.id,`${x.parameters.competitor?'mit':'ohne'} Mitnutzer; Ertrag ${x.result.yield}; ${x.parameters.intraspecific?'gleiche':'verschiedene'} Art`]),a.controlId)}${select('competitor-id','Vergleichslauf',l.experiments.map(x=>[x.id,`${x.parameters.competitor?'mit':'ohne'} Mitnutzer; Ertrag ${x.result.yield}`]),a.competitorId)}${checks('event-ids',events,chosenEvents)}${select('claim','Meine Aussage',[['resource-limits-yield','Begrenzte gemeinsame Ressource vermindert den Ertrag'],['event-with-resource','Ein Vorgang mit konkreter Ressource / Partner ist dokumentiert'],['presence-proves','Gemeinsame Anwesenheit beweist schon eine Wechselwirkung']],a.claim)}${select('alternative','Kontrolle / Aussagegrenze',[['tide-controlled','Gleiche Tide kontrolliert den alternativen Zugang'],['resource-controlled','Gleicher Startpool kontrolliert die Ressourcenmenge'],['no-population-inference','Ein Einzelereignis belegt keine Populationsregel'],['no-seed-guarantee','Pollentransport garantiert keine Samenbildung'],['not-full-mineralization','Einziehen ist keine vollständige Mineralisierung'],['everything-proven','Das Modell beweist die Beziehung in der Natur']],a.alternative)}`;
  }else if(id==='K3'){
   body=`<p>Am Watt-Probenpunkt wird eine Muschel als individuelles Schnittmodell untersucht. Nutze ausdrücklich gesteuerte Modellzeitfenster: erst Niedrigwasser, später Hochwasser. Stelle und 5-cm-Tiefe bleiben gleich. Die Protokolle zählen nicht als sechs Sekunden eigener Fernglassichtung.</p><p>Erfasste Protokolle: ${l.protocols.length}. ${l.level==='eA'?'Zusätzlich Q1, Q2 und die Nullprobe Q0 aufnehmen.':''}</p>${select('low-id','Früheres Niedrigwasserprotokoll',l.protocols.map(p=>[p.id,`${p.individualId} · ${p.activity} · t=${p.simulationTime.toFixed(1)} s · ${p.duration} s`]),a.lowId)}${select('high-id','Späteres Hochwasserprotokoll',l.protocols.map(p=>[p.id,`${p.individualId} · ${p.activity} · t=${p.simulationTime.toFixed(1)} s · ${p.duration} s`]),a.highId)}${select('filtration','Wann ist Filtration in diesem Modell möglich?',[['covered','Bei Wasserbedeckung'],['always','Immer, auch trocken']],a.filtration)}${select('access','Wann ist die Oberfläche für den Austernfischer besser erreichbar?',[['exposed','Beim Trockenfallen'],['covered','Bei hohem Wasserstand']],a.access)}${select('absence','Wie deute ich einen Nullfund?',[['not-detected','Unter dieser Methode nicht nachgewiesen'],['extinct','Dort ist die Art sicher ausgestorben']],a.absence)}${select('depth','Was bewirkt eine andere Untersuchungstiefe?',[['different-space','Sie verändert den Untersuchungsraum und die Vergleichbarkeit'],['irrelevant','Sie ist für den Vergleich egal']],a.depth)}${samplesTable(l.samples)}`;
  }else if(id==='K4'){
   body=`<p>Sichere einen eigenen Beleg von Regenwurm/Streu oder Zunderschwamm/Totholz. Ergänze ausdrücklich das bereitgestellte Bodenschnittmodell. Pfeile zeigen den Stofffluss von Quelle zu Empfänger; Nahrungsbeziehungen zusätzlich Energiefluss.</p><div class="section-model"><p>Blattstreu → Regenwurm: Einziehen/Zerkleinern/Einmischen.</p><p>Organische Reste → saprotrophe Mikroorganismen → CO₂ und mineralische Nährstoffe.</p><p>Wurzel → Zucker → Mykorrhizapilz; Pilz → Wasser/Mineralstoffe → Wurzel. Dieser Austausch ist eine bereitgestellte Modellergänzung.</p></div>${checks('edges',FOOD_EDGES.map(([x,y])=>[x+'>'+y,`${NODE_LABELS[x]} → ${NODE_LABELS[y]}`]),(a.edges||[]).map(x=>x.join('>')))}${select('energy','Was geschieht mit der Energie?',[['heat-not-cycle','Gerichteter Fluss; Entwertung als Wärme, kein Energiekreislauf'],['energy-cycle','Sie kreist verlustfrei zurück']],a.energy)}${select('mineralization','Wer mineralisiert?',[['microbes-not-worm-alone','Mikroorganismen; der Regenwurm bereitet Material vor'],['worm-alone','Der Regenwurm mineralisiert allein vollständig']],a.mineralization)}`;
  }else if(id==='K5'){
   body=`${MANAGEMENT_CARDS.map(c=>`<article><h3>${e(c.perspective||c.option)}</h3><p>${e(c.fact||c.effect)}</p><p>${e(c.value?'Wert: '+c.value+' · Interesse: '+c.interest:'Kosten/Folgen: '+c.cost)}</p></article>`).join('')}${select('decision','Meine Option',[['reroute','Umleitung'],['seasonal-rest','Saisonale Ruhe'],['raised-boardwalk','Erhöhter Bohlenweg']],a.option)}${checks('criteria',CRITERIA,a.criteria||[])}<div class="table-scroll"><table><tr><th>Kriterium</th><th>Mein Gewicht (0–10)</th></tr>${CRITERIA.map(([id,label])=>`<tr><td>${e(label)}</td><td><input aria-label="Gewicht ${e(label)}" id="weight-${id}" type="number" min="0" max="10" step="1" value="${a.weights?.[id]??0}"></td></tr>`).join('')}</table></div>${checks('evidence-ids',journal.data.records.map(r=>[r.id,fundLabel(r,journal.data)+' · '+visibleIdentity(r)]),a.evidenceIds||[])}${select('link-record','Beleg für meine Verknüpfung',journal.data.records.map(r=>[r.id,fundLabel(r,journal.data)]),a.evidenceLinks?.[0]?.recordId)}${select('link-criterion','Damit verbundenes Kriterium',CRITERIA,a.evidenceLinks?.[0]?.criterion)}<label>Welche Bedeutung hat dieser Beleg für das Kriterium?<textarea id="evidence-meaning" maxlength="2000">${e(a.evidenceLinks?.[0]?.meaning||'')}</textarea></label>${[['fact','Sachinformation und Herkunft'],['value','Mein Wert / Interesse'],['norm','Meine Handlungsnorm (Soll-Aussage)'],['consequence','Erwartete Folge und mögliche Nebenfolge']].map(([id,label])=>`<label>${e(label)}<textarea id="${id}" maxlength="2000">${e(a[id]||'')}</textarea></label>`).join('')}<p>Gespräche im Dorf: ${[...new Set((l.perspectives||[]).map(p=>p.speakerId))].map(id=>e(MANAGEMENT_CARDS.find(c=>c.id===id)?.perspective)).join(', ')||'noch keine notiert'}. Nutze sie als verfasste Perspektiven, getrennt von eigenen Küstenbelegen. Kosten benötigen zusätzliche Informationen.</p>${select('alternative','Meine Alternative',[['reroute','Umleitung'],['seasonal-rest','Saisonale Ruhe'],['raised-boardwalk','Erhöhter Bohlenweg']],a.alternative)}${select('uncertainty','Wesentliche Unsicherheit',[['seasonal-transfer','Beobachtungsfenster nicht auf alle Jahreszeiten übertragbar'],['limited-model','Modell vereinfacht Störung und Landschaft'],['cost-uncertain','Reale Bau-/Unterhaltungskosten fehlen']],a.uncertainty)}${select('fact-value','Wie behandle ich Fakten und Werte?',[['facts-and-values-separated','Getrennt benennen und dann begründet abwägen'],['facts-decide','Naturdaten entscheiden allein das richtige Werturteil']],a.factValue)}`;
  }
  panel(`<span class="eyebrow">${id} · ${e(journal.data.learning.level)}</span><h2>${e(m.title)}</h2><button id="back-hub">Andere Frage / freie Erkundung</button><div id="task-form">${body}<label>Meine Behauptung, Begründung, Gegenhypothese und offene Frage<textarea id="reasoning" maxlength="4000">${e(a.reasoning||'')}</textarea></label><p class="fine">Freier Text wird gespeichert und zur Besprechung genutzt. Er wird nicht per Stichwort als fachlich richtig bewertet.</p><div class="actions"><button id="save-task">Antworten sichern und Belegstruktur prüfen</button><button id="export-task">Feldbuch mit aktueller Eingabe als Datei sichern</button></div><p id="task-feedback" role="status"></p></div><p id="learning-status" role="alert"></p>`);
  $('back-hub').onclick=hub;
  const read=()=>{const value={...a,reasoning:$('reasoning').value};if(id==='K1')return {...value,recordId:$('determination-record').value,features:selected('features'),choice:$('choice')?.value||'',limit:$('limit')?.value||''};if(id==='K2')return {...value,caseId:$('case-id').value,experimentTide:$('experiment-tide').value,controlId:$('control-id').value,competitorId:$('competitor-id').value,eventIds:selected('event-ids'),claim:$('claim').value,alternative:$('alternative').value};if(id==='K3')return {...value,lowId:$('low-id').value,highId:$('high-id').value,filtration:$('filtration').value,access:$('access').value,absence:$('absence').value,depth:$('depth').value};if(id==='K4')return {...value,edges:selected('edges').map(x=>x.split('>')),energy:$('energy').value,mineralization:$('mineralization').value};return {...value,weights:Object.fromEntries(CRITERIA.map(([id])=>[id,Number($('weight-'+id).value)])),evidenceLinks:[{recordId:$('link-record').value,criterion:$('link-criterion').value,meaning:$('evidence-meaning').value}],fact:$('fact').value,value:$('value').value,norm:$('norm').value,consequence:$('consequence').value,option:$('decision').value,criteria:selected('criteria'),evidenceIds:selected('evidence-ids'),alternative:$('alternative').value,uncertainty:$('uncertainty').value,factValue:$('fact-value').value};};
  autosave(id,read);submit(id,read);$('export-task').onclick=()=>safe(()=>{const value=read(),candidate={...journal.data,learning:{...journal.data.learning,answers:{...journal.data.learning.answers,[id]:value},drafts:{...journal.data.learning.drafts,[id]:value}}},valid=parseCompact(JSON.stringify(candidate));download('ranger-kompakt-feldbuch-mit-eingabe.json',JSON.stringify(valid,null,2));api.setDirty(false);toast('Datei enthält die aktuelle Eingabe; der lokale Speicher wurde nicht ersetzt.');});
  if(id==='K1'){$('determination-record').onchange=()=>safe(()=>{const value=read();persist({drafts:{...l.drafts,[id]:{...value,features:[],choice:'',limit:''}}});task(id);});$('add-determination').onclick=()=>safe(()=>{const value=read(),d={recordId:value.recordId,features:value.features,choice:value.choice,limit:value.limit};value.determinations=[...(a.determinations||[]).filter(x=>x.recordId!==d.recordId),d];journal.answer(id,value);persist({drafts:{...journal.data.learning.drafts,[id]:value}});task(id);});}
  if(id==='K2')for(const [button,competitor]of [['run-control',false],['run-competitor',true]])$(button).onclick=()=>safe(()=>{const value=read(),parameters={competitor,intraspecific:$('case-id').value==='same-species-competition',tide:$('experiment-tide').value,seed:state.initialSeed,initial:12},experiment={id:uid(),source:'controlled-model',parameters,result:competitionExperiment(parameters),...context()};persist({experiments:[...journal.data.learning.experiments,experiment],drafts:{...journal.data.learning.drafts,[id]:value}});task(id);$('experiment-table').closest('details').open=true;});
 }
 function experimentTable(rows){return rows.length?`<table><caption>Kontrollierte Modellläufe</caption><tr><th>Mitnutzer</th><th>Typ</th><th>Ertrag</th><th>Rest</th></tr>${rows.map(r=>`<tr><td>${r.parameters.competitor?'mit':'ohne'}</td><td>${r.parameters.intraspecific?'intra':'inter'}</td><td>${r.result.yield}</td><td>${r.result.remaining}</td></tr>`).join('')}</table>`:'<p>Noch kein Kontrolllauf.</p>';}
 function samplesTable(rows){return rows.length?`<table><caption>Modellproben · keine Naturdichte</caption><tr><th>Quadrat</th><th>Anzahl</th><th>m²</th><th>Ind./m²</th></tr>${rows.map(r=>`<tr><td>${e(r.quadratId)}</td><td>${r.count}</td><td>${r.areaM2}</td><td>${(r.count/r.areaM2).toFixed(2)}</td></tr>`).join('')}</table>`:'<p>Noch keine Flächenprobe.</p>';}
 const stations=[{id:'forest-core',name:'Waldkern: Standort und Zweig',x:-57,z:7},{id:'forest-edge',name:'Saum: Blattfenster',x:-43,z:12},{id:'flower',name:'Sonniger Dorfsaum: Blütenfenster',x:-25,z:9},{id:'wood',name:'Totholz und Streu',x:-62,z:-2.3},{id:'coast',name:'Watt-Probenpunkt',x:63,z:-12},{id:'mussels',name:'Muschelbank',x:61,z:-14},{id:'outlook',name:'Priel am Beobachtungssteg',x:63,z:4},{id:'creek-east',name:'Prielblick am östlichen Steg',x:73,z:2},{id:'marsh',name:'Salzwiesen-Transekt',x:36,z:18},{id:'upper-marsh',name:'Obere Salzwiese',x:25,z:20},{id:'lower-marsh',name:'Untere Salzwiese',x:37,z:-17},{id:'pioneer-marsh',name:'Pionierzone',x:49,z:-3},{id:'grass-marsh',name:'Schlickgras-Horste',x:46,z:-13},{id:'shrub-marsh',name:'Keilmelde auf höherem Salzwiesenstandort',x:35,z:10},{id:'oak',name:'Eichenstelle',x:-37,z:-9},{id:'dusk',name:'Deckungsreicher Waldsaum',x:-62,z:-20},{id:'village',name:'Dorfkonferenz',x:-21,z:4}];
 function nearestStation(){return stations.map(s=>({...s,distance:Math.hypot(s.x-observer.x,s.z-observer.z)})).sort((a,b)=>a.distance-b.distance)[0];}
 function talk(id){
  const speaker=nearestSpeaker(observer);if(speaker.id!==id||speaker.distance>2.7){toast('Gehe zur Gesprächsperson im Dorf.');return;}
  const c=MANAGEMENT_CARDS.find(c=>c.id===id);panel(`<span class="eyebrow">GESPRÄCH AM ORT · MODELLDIALOG</span><h2>${e(speaker.name)}</h2><p>${e(c.fact)}</p><p>Mein Anliegen: ${e(c.interest)}. Mein Wert: ${e(c.value)}.</p><p>Diese verfasste Perspektive ist keine befragte reale Person und kein eigener Organismenbeleg. Trenne sie in K5 von deiner Beobachtung und eigenen Wertung.</p><button id="remember-perspective">Gespräch für die Dorfkonferenz notieren</button><button id="dialogue-task">K5 öffnen</button><p id="learning-status" role="alert"></p>`);
  $('remember-perspective').onclick=()=>safe(()=>{persist({perspectives:[...(journal.data.learning.perspectives||[]),{id:uid(),speakerId:id,source:'model-dialogue',x:observer.x,z:observer.z,...context()}]});status('Gespräch mit Ort und Modellzeit vermerkt; keine Sichtungs- oder Kompetenzgutschrift.');});
  $('dialogue-task').onclick=()=>task('K5');
 }
 function study(){const station=nearestStation();if(station.distance>8){toast('Gehe zu einem Untersuchungsort: Waldkern, Saum, Totholz, Dorf oder Watt-Probenpunkt.');return;}
  const candidates=[...state.plants,...(state.treeSamples||[]),state.deer,state.bird,...state.ecology.actors.filter(a=>a.visible&&a.alive)].filter(a=>Math.hypot(a.x-station.x,a.z-station.z)<(station.id==='coast'?14:8));const unique=candidates.filter((a,i,all)=>all.findIndex(b=>b.taxon===a.taxon&&b.stage===a.stage)===i);
  panel(`<span class="eyebrow">UNTERSUCHUNGSORT</span><h2>${e(station.name)}</h2><p>Vergrößerte Ansichten zeigen das aktive Modell desselben Individuums. Bodenschnitte und Modellmessungen sind ausdrücklich ergänzte Untersuchungen. Auswahl allein vergibt keinen Beleg.</p><div class="actions">${unique.map(a=>`<button data-inspect="${e(a.id)}" data-taxon="${e(a.taxon)}" data-stage="${e(a.stage||'adult')}">Nahansicht: ${e(fundLabel(a,journal.data))}${a.stage==='caterpillar'?' · Raupe':''}</button>`).join('')}</div>${['coast','mussels','outlook','creek-east'].includes(station.id)?`<h3>Nahrungssuche am erreichten Ort</h3><p>Die Beute dieses Rundgangs ist endlich und kann während des Waldaufenthalts aufgebraucht werden. Du kannst hier ausdrücklich einen neuen Modellrundgang bei Zeit 0 beginnen. Dein Standort und Feldbuch bleiben erhalten; Tiere und endliche Ressourcen beginnen im Ausgangszustand. Das ist ein neues Beobachtungsfenster, keine natürliche Nachlieferung. Belege aus verschiedenen Rundgängen ergeben keinen kontrollierten K3-Vergleich.</p><button id="new-observation-context">Neues Beobachtungsfenster hier beginnen · Modellzeit 0</button><p id="observation-context-status">Aktueller Rundgang: ${e(api.context().runId)} · ${state.time.toFixed(1)} Modell-s.${api.context().sceneOrigin?' Neu begonnen am Küstenort; Herkunft wird mit jedem Beleg gesichert.':''}</p><p>Wähle einen Vogel. Die Kamera dreht sich an deinem Standort mit. In Echtzeit zählen nur aktive, freie Sicht und die normale Beobachtungsdauer; die Auswahl allein erzeugt keinen Beleg. Modellschritte halten zwischen den Schritten an und zählen nicht als eigene Sichtungszeit.</p><div class="actions">${state.ecology.actors.filter(a=>COASTAL_PROFILES[a.taxon]).map(a=>'<button data-realtime="'+e(a.id)+'">'+e(fundLabel(a,journal.data))+' · Echtzeit beobachten</button><button data-behavior="'+e(a.id)+'">'+e(fundLabel(a,journal.data))+' verfolgen</button>').join('')}</div>`:''}${station.id.startsWith('forest')?'<button id="measure-site">Standort mit derselben Modellmethode protokollieren</button>':''}${['coast','mussels'].includes(station.id)?`<h3>Kontrollierter Muschelvergleich</h3><p>Aktuelle Tide: ${e(state.ecology.tide.label)}; Modellzeit ${state.time.toFixed(1)} s. Die folgenden Tasten steuern ausdrücklich die Modellzeit; sie ersetzen keine aktive Sichtungszeit.</p><label>Konkretes Individuum<select id="specimen">${state.ecology.actors.filter(a=>a.taxon==='cerastoderma_edule').map(a=>option(a.id,a.id,'compact-cockle-0')).join('')}</select></label><div class="actions"><button id="next-low">Nächste Niedrigwasserphase</button><button id="next-high">Nächste Hochwasserphase</button><button id="coast-protocol">6 Modellsekunden protokollieren · 5 cm</button></div><h3>Feste Flächenprobe</h3><p>Je 0,27 m², 5 cm Tiefe; lebende Muscheln nach ID einmal zählen. Q0 darf null sein.</p><div class="actions">${['Q1','Q2','Q0'].map(q=>`<button data-sample="${q}">${q} protokollieren</button>`).join('')}</div>${samplesTable(journal.data.learning.samples)}`:''}${station.id==='marsh'?'<p>Von oberer Salzwiese über unteren Rasen zur Pionierzone: Höhe, Entwässerung und Überflutungsregime getrennt notieren. Gras-Feinbestimmung kann unsicher bleiben. Raumzonierung ist keine Zeitreihe.</p>':''}${station.id==='village'?'<button id="village-task">Dorfkonferenz öffnen</button>':''}<details><summary>Sechs Funktionsgruppen im Schnittmodell</summary>${FUNCTIONAL_GROUPS.map(g=>`<p><strong>${e(g.name)}</strong>: ${e(g.role)}. Bereitgestellte funktionale Ergänzung, keine neue Sammelart.</p>`).join('')}</details><p id="learning-status" role="alert"></p>`);
  document.querySelectorAll('[data-behavior]').forEach(b=>b.onclick=()=>api.observeBehavior(b.dataset.behavior));
  document.querySelectorAll('[data-realtime]').forEach(b=>b.onclick=()=>api.observeBehavior(b.dataset.realtime,true));
  if($('new-observation-context'))$('new-observation-context').onclick=()=>safe(()=>{api.newObservationContext(station.id);study();});
  document.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>api.inspect(candidates.find(a=>a.id===b.dataset.inspect)));
  if($('measure-site'))$('measure-site').onclick=()=>safe(()=>{const m={...forestMeasurement(state,observer.x,observer.z),id:uid(),instrument:'relative-light-and-moisture',...context()};persist({measurements:[...journal.data.learning.measurements,m]});status('Standortprotokoll gesichert: relatives Modelllicht '+m.relativeLight+'; '+m.moistureClass+'. Keine Lux-/Nitratmessung.');});
  for(const [button,phase]of [['next-low',0],['next-high',60]])if($(button))$(button).onclick=()=>safe(()=>{let target=Math.floor(state.time/120)*120+phase;if(target<=state.time+.01)target+=120;api.advance(target-state.time);study();});
  if($('coast-protocol'))$('coast-protocol').onclick=()=>safe(()=>{const id=$('specimen').value,start=state.time;const snapshots=[];for(let i=0;i<60;i++){api.advance(.1);snapshots.push(stationSnapshot(state,id));}const snap=stationSnapshot(state,id),stable=Array.from({length:61},(_,i)=>tideAt(start+i/10).waterLevel>snap.sedimentSurface?'filtering':'resting').every(a=>a===snap.activity),p={...snap,id:uid(),...context(),duration:6,simulationTime:state.time,stableState:stable,source:'model-protocol'};persist({protocols:[...journal.data.learning.protocols,p]});status('Modellprotokoll gesichert: '+snap.individualId+' · '+snap.activity+' · '+(stable?'stabiles Fenster':'Zustandswechsel im Fenster; kein voller Vergleichsbeleg')+'.');});
  document.querySelectorAll('[data-sample]').forEach(b=>b.onclick=()=>safe(()=>{const q=sampleQuadrat(state,b.dataset.sample);persist({samples:[...journal.data.learning.samples,{...q,id:uid(),quadratId:q.id,...context()}]});study();}));if($('village-task'))$('village-task').onclick=()=>{safe(()=>persist({activeMission:'K5'}));task('K5');};
 }

 function materials(){panel(`<span class="eyebrow">LERNPAKET · gA / eA</span><h2>Quellen prüfen, Grenzen erklären.</h2><p>25 Unterrichtskarten ergänzen die fünf Kernfamilien. Die Fachanforderungen Schleswig-Holstein 2026 und der Leitfaden 2017 sind im Original abgeglichen. Das ETS-Schulcurriculum konnte nicht im Original abgerufen werden. Quellenwerte, gestaltete Modelldaten und offene Datenlücken sind jeweils gekennzeichnet.</p><div class="actions"><button id="student-material">Arbeitsblätter herunterladen</button><button id="teacher-material">Lehrkräftefassung herunterladen</button><button id="open-analysis">Datenmodelle öffnen</button></div>${MATERIALS.map(c=>`<details><summary>${c.id} · ${e(c.title)} · ${e(c.level)}</summary><p>${e(c.data)}</p>${resourceHTML(c,e)}<p><strong>Auftrag:</strong> ${e(c.task)}</p>${(c.helps||[]).length?'<details><summary>Gestufte Hilfen</summary>'+c.helps.map(h=>'<p>'+e(h)+'</p>').join('')+'</details>':''}<p class="fine">${e(c.limit)}</p><details><summary>Erwartungskriterien für die Besprechung</summary><ul>${c.expected.map(x=>`<li>${e(x)}</li>`).join('')}</ul></details>${c.sources.map(k=>`<p><a target="_blank" rel="noopener noreferrer" href="${e(SOURCES[k].url)}">${e(SOURCES[k].title)}</a></p>`).join('')}</details>`).join('')}`);$('student-material').onclick=()=>download('Ranger-Kompakt-Arbeitsblaetter.html',materialHTML(false),'text/html;charset=utf-8');$('teacher-material').onclick=()=>download('Ranger-Kompakt-Lehrkraefte.html',materialHTML(true),'text/html;charset=utf-8');$('open-analysis').onclick=analysis;}
 const modelSpecs={growth:{label:'Exponentiell / logistisch · eA',fn:growthModel,fields:[['initial','N₀',10,0,1000000],['rate','r pro Tag',.25,0,2],['capacity','K',100,.001,10000000],['days','Modelltage',20,1,365]]},predator:{label:'Lotka–Volterra · schulintern',fn:predatorPreyModel,fields:[['prey','Beute N₀',30,.01,1000],['predator','Räuber N₀',6,.01,1000],['days','Modelltage',40,1,200]],check:['disturbance','Beide Populationen zur Halbzeit halbieren']},tolerance:{label:'Toleranz / Konkurrenz',fn:toleranceModel,fields:[],check:['competitor','Mit gestaltetem Konkurrenten']},carbon:{label:'Kohlenstoff / Fließgleichgewicht',fn:carbonModel,fields:[['days','Modelltage',30,1,365],['photosynthesis','Photosynthese: C-Einheiten/Tag',3,0,10],['plantRespiration','Pflanzenatmung: C-Einheiten/Tag',.8,0,10],['detritusInput','Streufluss: C-Einheiten/Tag',1,0,10]]},nitrogen:{label:'Stickstoffformen · eA',fn:nitrogenModel,fields:[['days','Modelltage',20,1,365],['input','N-Zufuhr: relative N-Einheiten/Tag',0,0,20]],check:['oxygen','Sauerstoff verfügbar']}};
 function plot(model){const rows=model.rows,xKey='t'in rows[0]?'t':'flooding',series=Object.keys(rows[0]).filter(k=>k!==xKey&&k!=='total'),maxX=Math.max(...rows.map(r=>r[xKey])),maxY=Math.max(1,...rows.flatMap(r=>series.map(k=>r[k]))),colors=['#426e57','#ac7049','#72719b','#7896a1','#9f8e44'];return `<svg viewBox="0 0 600 290" role="img" aria-label="${e(model.kind)}: synthetische Modellkurven"><path d="M45 15V245H585" fill="none" stroke="#727c69"/>${series.map((k,i)=>`<polyline fill="none" stroke="${colors[i%colors.length]}" stroke-width="2" points="${rows.map(r=>(45+r[xKey]/maxX*530).toFixed(2)+','+(245-r[k]/maxY*220).toFixed(2)).join(' ')}"/><text x="${50+i*105}" y="275" font-size="11" fill="${colors[i%colors.length]}">${e(k)}</text>`).join('')}<text x="10" y="20" font-size="10">${maxY.toFixed(1)}</text><text x="530" y="250" font-size="10">${maxX} ${e(xKey)}</text></svg>`;}
 function analysis(type='growth'){if(typeof type!=='string')type='growth';const spec=modelSpecs[type];let last=null;panel(`<span class="eyebrow">ZUSATZMODELLE · KEINE NATURDATEN</span><h2>Vorhersagen prüfen.</h2><p>Jedes Modell nennt Einheiten, Anfangsbedingungen und Grenzen. Änderungen erzeugen Zahlenmodelle, keine zusätzlichen Tierpopulationen in der Landschaft.</p><label>Modell<select id="model-type">${Object.entries(modelSpecs).map(([id,m])=>option(id,m.label,type)).join('')}</select></label><form id="model-form">${spec.fields.map(([key,label,value,min,max])=>`<label>${e(label)}<input id="parameter-${key}" name="${key}" type="number" min="${min}" max="${max}" step="${key==='days'?1:'any'}" value="${value}" required></label>`).join('')}${spec.check?`<label class="check"><input type="checkbox" id="model-check"${type==='nitrogen'?' checked':''}>${e(spec.check[1])}</label>`:''}<button id="run-model" type="submit">Modell berechnen</button></form><div id="model-output"></div><p id="learning-status" role="alert"></p>`);$('model-type').onchange=()=>analysis($('model-type').value);$('model-form').onsubmit=event=>{event.preventDefault();last=null;$('model-output').replaceChildren();$('learning-status').textContent='';safe(()=>{const parameters=Object.fromEntries(spec.fields.map(([key])=>[key,Number($('parameter-'+key).value)]));if(spec.check)parameters[spec.check[0]]=$('model-check').checked;last=spec.fn(parameters);$('model-output').innerHTML=`<p class="badge">${e(last.source)} · synthetisches Modell</p>${plot(last)}<p>Einheiten: ${e(JSON.stringify(last.units))}</p><p>Parameter: ${e(JSON.stringify(last.parameters))}</p><p>${e(last.assumptions)}</p>${last.processes?'<ul>'+last.processes.map(p=>'<li>'+e(p)+'</li>').join('')+'</ul>':''}<button id="export-model">Tabelle und Modellherkunft als JSON sichern</button><details><summary>Vollständige Datentabelle</summary><div class="table-scroll"><table><tr>${Object.keys(last.rows[0]).map(k=>'<th>'+e(k)+'</th>').join('')}</tr>${last.rows.map(row=>'<tr>'+Object.values(row).map(v=>'<td>'+Number(v).toFixed(4)+'</td>').join('')+'</tr>').join('')}</table></div></details>`;$('export-model').onclick=()=>download('ranger-modell-'+last.kind+'.json',JSON.stringify(last,null,2));});};}
 refreshHud();return {hub,task,study,talk,materials,analysis,materialHTML,nearestStation,refreshHud,stations};
}
